<script setup lang="ts">
import{computed}from'vue';import{UsersRound,Vote,UserRoundMinus,CheckCheck,FileMinus,FileX}from'lucide-vue-next';import type{Statistics}from'../../types/election';import{number,percent}from'../../utils/format';const p=defineProps<{stats:Statistics|null}>();const items=computed(()=>[{label:'Eleitorado',value:p.stats?.electorate,detail:'Eleitores aptos a votar',icon:UsersRound},{label:'Comparecimento',value:p.stats?.attendance,detail:percent(p.stats?.attendancePercent)+' do eleitorado totalizado',icon:Vote},{label:'Abstenções',value:p.stats?.abstentions,detail:percent(p.stats?.abstentionPercent)+' do eleitorado totalizado',icon:UserRoundMinus},{label:'Votos válidos',value:p.stats?.valid,detail:'Votos válidos computados',icon:CheckCheck},{label:'Votos brancos',value:p.stats?.blank,detail:percent(p.stats?.blankPercent)+' dos votos apurados',icon:FileMinus},{label:'Votos nulos',value:p.stats?.null,detail:percent(p.stats?.nullPercent)+' dos votos apurados',icon:FileX}]);
</script>
<template><section class="statistics-section"><div class="section-heading"><h2>A apuração em números</h2><span class="muted small">Dados desta localização</span></div><div class="statistics-grid"><div v-for="item in items" :key="item.label" class="stat-card"><div><span>{{item.label}}</span><component :is="item.icon" :size="18"/></div><strong>{{number(item.value)}}</strong><small>{{item.detail}}</small></div></div></section></template>
